import fs from 'node:fs';import path from 'node:path';import crypto from 'node:crypto';
const w=process.cwd(),out='/Users/hishamel-husseini/Documents/projects/raffle-fun/audits/2026-10-21-r001/runs/OPENAI-GEBAL/attempt-02';const sha=b=>crypto.createHash('sha256').update(b).digest('hex');
const ledger=JSON.parse(fs.readFileSync('stage-ledger.json'));const s=ledger.stages.find(x=>x.id==='S04');s.sealVerification={path:'evidence/adjudication-seal-verification.json',sha256:sha(fs.readFileSync('evidence/adjudication-seal-verification.json'))};ledger.delivery={preparedAt:new Date().toISOString(),destination:out,preexistingOutputFiles:['command.json','events.jsonl','prompt.txt','runner-selection.json','stderr.txt'],preexistingContentsRead:false,preexistingFilesOverwritten:false,workingCachesAndTemporaryFilesRetained:true,bundleManifest:'BUNDLE-MANIFEST.json',deliveryVerification:'DELIVERY.json'};fs.writeFileSync('stage-ledger.json',JSON.stringify(ledger,null,2)+'\n');
const rootFiles=fs.readdirSync(w,{withFileTypes:true}).filter(d=>d.isFile()).map(d=>d.name);const rootDirs=['evidence','work','gebal-state'];
for(const name of [...rootFiles,...rootDirs]){if(fs.existsSync(path.join(out,name)))throw Error('Refuse overwrite existing output '+name);}
fs.mkdirSync(out,{recursive:true});for(const name of rootFiles)fs.copyFileSync(path.join(w,name),path.join(out,name),fs.constants.COPYFILE_EXCL);for(const name of rootDirs)fs.cpSync(path.join(w,name),path.join(out,name),{recursive:true,errorOnExist:true,force:false,dereference:false});
const files=[];function walk(dir,rel=''){for(const d of fs.readdirSync(dir,{withFileTypes:true})){const r=path.join(rel,d.name),full=path.join(dir,d.name);if(d.isDirectory())walk(full,r);else if(d.isFile())files.push(r);else throw Error('Unexpected non-file '+r);}}
for(const name of rootFiles)files.push(name);for(const name of rootDirs)walk(path.join(w,name),name);
const entries=files.sort().map(p=>{const a=fs.readFileSync(path.join(w,p)),b=fs.readFileSync(path.join(out,p));const h=sha(a);if(h!==sha(b))throw Error('Copy mismatch '+p);return {path:p,sha256:h,bytes:a.length};});
