const deliveredAt=new Date().toISOString();const delivery={deliveredAt,filesCopied:entries.length,allCopiedHashesMatch:true,manifestSha256:sha(fs.readFileSync(path.join(w,'BUNDLE-MANIFEST.json'))),stageLedgerSha256:sha(fs.readFileSync(path.join(w,'stage-ledger.json'))),originalSealSha256:sha(fs.readFileSync(path.join(w,'SEAL.json'))),originalFirstPassSha256:sha(fs.readFileSync(path.join(w,'FIRST-PASS.md'))),finalNativeReportSha256:sha(fs.readFileSync(path.join(w,'report.native.final.json'))),runId:ledger.native.runId,sourceOnlyCompletion:ledger.completion.nativeSourceOnlyOwnModelWorkflow,testInclusive:'BLOCKED',elapsedMinutes:(Date.parse(deliveredAt)-Date.parse(ledger.startedAt))/60000,sourceUnchanged:true,originalSealUnchanged:true,preexistingFilesUntouched:true};for(const base of [w,out])fs.writeFileSync(path.join(base,'DELIVERY.json'),JSON.stringify(delivery,null,2)+'\n',{flag:'wx'});console.log(JSON.stringify(delivery,null,2));
